-- Full Stage 1 stored-configuration checker. READ ONLY: no application data is changed.
-- Run in SSMS against EEMSuite_Northlake, or:
-- sqlcmd -S . -d EEMSuite_Northlake -E -C -I -b -f 65001 -i checks.sql -y 0
-- (-f 65001 reads this UTF-8 file as UTF-8, so any non-ASCII text compares correctly.)
-- First row = overall PASS/FAIL; section summaries follow, then exact discrepancies.
-- Missing/extra/duplicate records and wrong values fail. Product-managed groups/users are excluded.
-- Shared copies are checked against the SAME recipe as their master; a wrong master cannot pass by matching its copies.
-- A copy the recipe lists as its own local record (made local with Make Local) is checked against that record instead.
-- A category grant (report "All", all task groups, all library rates) is one Key * row, which also covers keys
-- added to the catalog later. Grants waiting for a specific node or task group remain deferred.
-- This checks stored settings, not UI permission enforcement or successful login.
-- After changing YAML, refresh snapshots: python -m generators.stage_check_data (from repo root).
SET NOCOUNT ON;
-- Only session-local comparison tables are written.
DROP TABLE IF EXISTS #StageCheckExpected,#StageCheckActual,#StageCheckAdditional,#StageCheckIssues;
DECLARE @Stage int=1, @ShowDetails bit=1;
DECLARE @ExpectedSnapshot nvarchar(max),@ActualSnapshot nvarchar(max),@AdditionalSnapshot nvarchar(max);
IF OBJECT_ID(N'dbo.UserGroups_Shared_Sync') IS NULL
    THROW 51000, 'Stage 1 requires the product group-sharing upgrade.', 1;
