DECLARE @DeferredJson nvarchar(max) = N'{"groups":["Common | eem_gateway_tasks_readonly","Northlake University | nlu_gateway_tasks_readonly","Northlake University | nlu_bill_import_tasks","Northlake University | nlu_cra_bill_import_tasks"],"permissions":[]}';
-- END YAML EXPECTATIONS
;WITH Recipe AS (
    SELECT CheckName,Item,Fields FROM OPENJSON(@ExpectedJson)
    WITH(CheckName nvarchar(100) '$.check',Item nvarchar(1000) '$.item',Fields nvarchar(max) '$.fields' AS JSON)
), SharedRows AS (
    SELECT CheckName,Item,Fields FROM Recipe
    UNION ALL
    SELECT r.CheckName,CONCAT(c.Item,SUBSTRING(r.Item,7,1000)),r.Fields
    FROM Recipe r CROSS JOIN Recipe c
    JOIN Recipe g ON g.CheckName=N'04 Groups' AND JSON_VALUE(g.Fields,'$.Shared')=N'true'
                 AND (g.Item=r.Item OR LEFT(r.Item,LEN(g.Item)+3)=g.Item+N' | ')
    WHERE c.CheckName=N'01 Companies' AND r.CheckName IN(N'04 Groups',N'04 Permissions')
      AND r.Item LIKE N'Common | %'
      -- A copy made local (Make Local) is its own record in that company and no longer follows the master.
      AND NOT EXISTS(SELECT 1 FROM Recipe l WHERE l.CheckName=N'04 Groups' AND l.Item=CONCAT(c.Item,SUBSTRING(g.Item,7,1000)))
), ExpectedRows AS (
    -- Key * is the category wildcard and is stored as one row; one row per catalog key under it is not expected.
    SELECT CheckName,Item,Fields FROM SharedRows
)
SELECT @ExpectedSnapshot=(SELECT CheckName,Item,JSON_QUERY(Fields) AS Fields FROM ExpectedRows FOR JSON PATH);
;WITH ExpectedRows AS (
    SELECT * FROM OPENJSON(@ExpectedSnapshot) WITH(CheckName nvarchar(100),Item nvarchar(1000),Fields nvarchar(max) AS JSON)
), Recipe AS (
    SELECT CheckName,Item,Fields FROM OPENJSON(@ExpectedJson)
    WITH(CheckName nvarchar(100) '$.check',Item nvarchar(1000) '$.item',Fields nvarchar(max) '$.fields' AS JSON)
), AddressEntities AS (
    SELECT N'01 Company addresses' AS CheckName,c.CompanyName AS Item,c.AD_AddressID FROM dbo.Company_TBL c WHERE c.CompanyID>0
    UNION ALL SELECT N'02 Provider addresses',p.Name,p.AD_AddressID FROM dbo.UtilityProvider p
    UNION ALL SELECT N'02 Remit addresses',CONCAT(p.Name,N' | ',a.AD_Address1),r.AD_AddressID
    FROM dbo.ProviderRemitAddr r JOIN dbo.UtilityProvider p ON p.ProviderID=r.ProviderID LEFT JOIN dbo.Address a ON a.AD_AddressID=r.AD_AddressID
), ContactEntities AS (
    SELECT N'01 Company contacts' AS CheckName,c.CompanyName AS Item,c.CT_ContactID FROM dbo.Company_TBL c WHERE c.CompanyID>0
    UNION ALL SELECT N'02 Provider contacts',p.Name,p.CT_ContactID FROM dbo.UtilityProvider p
), ActualRows AS (
    SELECT CONVERT(nvarchar(100),N'01 Companies') AS CheckName,CONVERT(nvarchar(1000),c.CompanyName) AS Item,
        (SELECT c.ArchiveInterval,tz.Description AS TimeZone,co.CO_CountryName AS Country FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) AS Fields
    FROM dbo.Company_TBL c LEFT JOIN dbo.TimeZone tz ON tz.TimeZoneID=c.TimeZoneID LEFT JOIN dbo.Country co ON co.CO_CountryCode=c.DefaultCountry WHERE c.CompanyID>0
    UNION ALL
    SELECT e.CheckName,e.Item,(SELECT a.AD_Address1 AS Address,a.AD_Address2 AS Address2,a.AD_City AS City,RTRIM(a.RE_RegionCode) AS Region,a.AD_PostalCode AS PostalCode,
        co.CO_CountryName AS Country,a.Latitude,a.Longitude FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM AddressEntities e LEFT JOIN dbo.Address a ON a.AD_AddressID=e.AD_AddressID LEFT JOIN dbo.Country co ON co.CO_CountryCode=a.CO_CountryCode
    UNION ALL
    SELECT e.CheckName,e.Item,(SELECT c.CT_FirstName AS FirstName,c.CT_LastName AS LastName,c.CT_Title AS Title,c.CT_Phone AS Phone,c.CT_Email AS Email FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM ContactEntities e LEFT JOIN dbo.Contact c ON c.CT_ContactID=e.CT_ContactID
    UNION ALL
    SELECT N'01 Hierarchy levels',CONCAT(c.CompanyName,N' | ',l.LevelNbr),
        (SELECT l.Description,CASE l.InternalLevelNbr WHEN 4 THEN N'Meter' ELSE i.Description END AS Type,l.UDFField AS UserDefinedField,l.Awesomefont AS Icon,l.InternalLevelNbr,l.MetaType
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.MetaLevel_TBL l JOIN dbo.Company_TBL c ON c.CompanyID=l.CompanyID LEFT JOIN dbo.InternalMetaLevel i ON i.InternalLevelNbr=l.InternalLevelNbr WHERE c.CompanyID>0
    UNION ALL
    SELECT N'01 Alarm settings',CONCAT(c.CompanyName,N' | ',a.Kind,N' | ',a.Severity),
        (SELECT a.Text,CONCAT(N'#',REPLACE(a.Color,N'#',N'')) AS Color FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.Company_TBL c CROSS APPLY(VALUES
        (N'Analog',N'Hi-Hi',c.TextHiHi,c.ColorHiHi),(N'Analog',N'Hi',c.TextHi,c.ColorHi),(N'Analog',N'Normal',c.TextNormal,c.ColorNormal),
        (N'Analog',N'Lo',c.TextLo,c.ColorLo),(N'Analog',N'Lo-Lo',c.TextLoLo,c.ColorLoLo),
        (N'Digital',N'0',NULL,c.State0),(N'Digital',N'1',NULL,c.State1),(N'Digital',N'2',NULL,c.State2),(N'Digital',N'3',NULL,c.State3)) a(Kind,Severity,Text,Color)
    WHERE c.CompanyID>0
    UNION ALL
    SELECT N'01 Bill scenarios',CONCAT(c.CompanyName,N' | ',s.ScenarioName),N'{"Present":true}'
    FROM dbo.BillScenario s JOIN dbo.Company_TBL c ON c.CompanyID=s.CompanyID WHERE c.CompanyID>0 AND s.ScenarioName=N'Actual'
    UNION ALL
    SELECT N'02 Providers',p.Name,(SELECT p.UtilProvDesc AS Description,p.URI AS Website,p.Awesomefont AS Icon FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.UtilityProvider p
    UNION ALL
    SELECT N'02 Bill cycles',CONCAT(p.Name,N' | ',b.BillCycle,N' | ',b.PeriodYear,N' | ',b.PeriodMonth),
        (SELECT CONVERT(date,b.StartDate) AS StartDate,CONVERT(date,b.EndDate) AS EndDate,b.Days,b.Description FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.BillCycle b JOIN dbo.UtilityProvider p ON p.ProviderID=b.ProviderID WHERE b.PeriodYear IN(2024,2025)
    UNION ALL
    SELECT N'02 Vendor associations',CONCAT(p.Name,N' | ',c.CompanyName),
        (SELECT cp.CP_VendorNbr AS VendorNumber,cp.CP_VendorNameAlias AS VendorNameAlias FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.CompanyProvider cp JOIN dbo.UtilityProvider p ON p.ProviderID=cp.ProviderID JOIN dbo.Company_TBL c ON c.CompanyID=cp.CompanyID WHERE c.CompanyID>0
    UNION ALL
    SELECT N'03 Company calendars',CONCAT(c.CompanyName,N' | ',cal.PeriodYear,N' | ',cal.PeriodMonth),
        (SELECT cal.CalendarTypeID,CONVERT(date,cal.StartDate) AS StartDate,CONVERT(date,cal.EndDate) AS EndDate,cal.Quarter,cal.PeriodDescription AS PeriodName FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.CompanyCalendar cal JOIN dbo.Company_TBL c ON c.CompanyID=cal.CompanyID WHERE c.CompanyID>0 AND cal.PeriodYear IN(2024,2025)
    UNION ALL
    SELECT N'04 Groups',CONCAT(c.CompanyName,N' | ',g.GroupID),(SELECT g.Name,g.IsShared AS Shared FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.UserGroups g JOIN dbo.Company_TBL c ON c.CompanyID=g.CompanyID
    WHERE g.IsSystemManaged=0 AND g.GroupID NOT IN(N'Public',N'Commoners',N'all rights')
      AND NOT EXISTS(SELECT 1 FROM OPENJSON(@DeferredJson,'$.groups') d WHERE d.value=CONCAT(c.CompanyName,N' | ',g.GroupID))
    UNION ALL
    SELECT N'04 Permissions',CONCAT(c.CompanyName,N' | ',p.GroupID,N' | ',p.PermissionType,N' | ',p.MetaKey),
        (SELECT p.PermissionType AS Type,p.MetaKey AS [Key],p.AuthLevel AS Level,p.MetaCompanyID,p.Effective,p.PermissionParentID FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.Permissions_TBL p JOIN dbo.Company_TBL c ON c.CompanyID=p.CompanyID
    JOIN ExpectedRows g ON g.CheckName=N'04 Groups' AND g.Item=CONCAT(c.CompanyName,N' | ',p.GroupID)
    WHERE NOT EXISTS(SELECT 1 FROM OPENJSON(@DeferredJson,'$.permissions') WITH(GroupID nvarchar(128),Type nvarchar(64)) d WHERE d.GroupID=p.GroupID AND d.Type=p.PermissionType)
    UNION ALL
    SELECT N'04 Scoped hierarchy',mw.MetaKey,(SELECT mw.CompanyID,mw.Description FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.MetaWorld_TBL mw JOIN Recipe r ON r.CheckName=N'04 Scoped hierarchy' AND r.Item=mw.MetaKey WHERE ISNULL(mw.DeleteInd,0)=0
    UNION ALL
    SELECT N'05 Users',u.UserID,(SELECT c.CompanyName AS Company,u.UserName AS DisplayName,u.Email,u.PrincipalType,u.AuthenticationPolicy,tz.Description AS TimeZone,
        CONVERT(bit,u.Inactive) AS Inactive,CONVERT(bit,CASE WHEN EXISTS(SELECT 1 FROM [Security].[EffectivePermission] p
            WHERE p.UserID=u.UserID AND p.CompanyID=u.CompanyID AND p.PermissionType=N'AR' AND p.AuthLevel=3
            AND p.MetaKey=CASE WHEN u.CompanyID=-1 THEN N'system_administrator' ELSE N'company_administrator' END) THEN 1 ELSE 0 END) AS IsAdmin
        FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.Users_TBL u JOIN dbo.Company_TBL c ON c.CompanyID=u.CompanyID LEFT JOIN dbo.TimeZone tz ON tz.TimeZoneID=u.TimeZoneID
    WHERE u.UserID NOT IN(N'Admin',N'dbo',N'reportemail',N'SiE_Setup',N'Worker')
    UNION ALL
    SELECT N'05 Memberships',CONCAT(c.CompanyName,N' | ',m.GroupID,N' | ',m.UserID),
        (SELECT home.CompanyName AS HomeCompany FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.UserGroupMember m JOIN dbo.UserGroups g ON g.CompanyID=m.CompanyID AND g.GroupID=m.GroupID
    JOIN dbo.Users_TBL u ON u.UserID=m.UserID JOIN dbo.Company_TBL c ON c.CompanyID=m.CompanyID JOIN dbo.Company_TBL home ON home.CompanyID=u.CompanyID
    WHERE g.IsSystemManaged=0 AND m.GroupID NOT IN(N'Public',N'Commoners',N'all rights')
      AND NOT EXISTS(SELECT 1 FROM OPENJSON(@DeferredJson,'$.groups') d WHERE d.value=CONCAT(c.CompanyName,N' | ',m.GroupID))
), AdditionalIssues AS (
    SELECT r.CheckName,r.Item,CONVERT(nvarchar(128),N'Permission catalog') AS Field,CONVERT(nvarchar(max),N'At least one active report') AS Expected,
        CONVERT(nvarchar(max),N'No active report in this category') AS Actual,N'FAIL' AS Severity
    FROM Recipe r WHERE r.CheckName=N'04 Permissions' AND JSON_VALUE(r.Fields,'$.Type') LIKE N'G:%' AND JSON_VALUE(r.Fields,'$.Key')=N'*'
      AND NOT EXISTS(SELECT 1 FROM dbo.PermissionCatalog p WHERE p.TypeKey COLLATE DATABASE_DEFAULT=JSON_VALUE(r.Fields,'$.Type') AND p.IsActive=1)
)
SELECT @ActualSnapshot=(SELECT CheckName,Item,JSON_QUERY(Fields) AS Fields FROM ActualRows FOR JSON PATH),
       @AdditionalSnapshot=(SELECT * FROM AdditionalIssues FOR JSON PATH);
-- Capture rows once so repeated summaries do not repeat database or JSON work.
SELECT * INTO #StageCheckExpected FROM OPENJSON(@ExpectedSnapshot)
WITH(CheckName nvarchar(100),Item nvarchar(1000),Fields nvarchar(max) AS JSON);
SELECT * INTO #StageCheckActual FROM OPENJSON(@ActualSnapshot)
WITH(CheckName nvarchar(100),Item nvarchar(1000),Fields nvarchar(max) AS JSON);
SELECT * INTO #StageCheckAdditional FROM OPENJSON(@AdditionalSnapshot)
WITH(CheckName nvarchar(100),Item nvarchar(1000),Field nvarchar(128),Expected nvarchar(max),Actual nvarchar(max),Severity nvarchar(4));
;WITH ExpectedRows AS (SELECT * FROM #StageCheckExpected),
ActualRows AS (SELECT * FROM #StageCheckActual),
AdditionalIssues AS (SELECT * FROM #StageCheckAdditional), ExpectedCounts AS (
    SELECT CheckName, Item, COUNT(*) AS RecordCount FROM ExpectedRows GROUP BY CheckName, Item
), ActualCounts AS (
    SELECT CheckName, Item, COUNT(*) AS RecordCount FROM ActualRows GROUP BY CheckName, Item
), Counts AS (
    SELECT COALESCE(e.CheckName,a.CheckName) AS CheckName, COALESCE(e.Item,a.Item) AS Item,
           ISNULL(e.RecordCount,0) AS ExpectedCount, ISNULL(a.RecordCount,0) AS ActualCount
    FROM ExpectedCounts e FULL JOIN ActualCounts a ON a.CheckName=e.CheckName AND a.Item=e.Item
), Issues AS (
    SELECT CheckName,Item,CONVERT(nvarchar(128),N'Presence / uniqueness') AS Field,
           CONVERT(nvarchar(max),ExpectedCount) AS Expected,CONVERT(nvarchar(max),ActualCount) AS Actual,N'FAIL' AS Severity
    FROM Counts WHERE ExpectedCount<>ActualCount OR ExpectedCount>1 OR ActualCount>1
    UNION ALL
    SELECT e.CheckName,e.Item,ef.[key] COLLATE DATABASE_DEFAULT,COALESCE(ef.value,N'(blank)'),COALESCE(af.value,N'(blank)'),N'FAIL'
    FROM ExpectedRows e JOIN ActualRows a ON a.CheckName=e.CheckName AND a.Item=e.Item
    JOIN Counts c ON c.CheckName=e.CheckName AND c.Item=e.Item AND c.ExpectedCount=1 AND c.ActualCount=1
    CROSS APPLY OPENJSON(e.Fields) ef
    OUTER APPLY (SELECT [key],value,[type] FROM OPENJSON(a.Fields) WHERE [key]=ef.[key]) af
    WHERE af.[key] IS NULL OR CASE WHEN (
        (ef.[type]=2 AND af.[type]=2
            AND COALESCE(TRY_CONVERT(decimal(38,6),ef.value),TRY_CONVERT(decimal(38,6),TRY_CONVERT(float,ef.value)))
                =COALESCE(TRY_CONVERT(decimal(38,6),af.value),TRY_CONVERT(decimal(38,6),TRY_CONVERT(float,af.value))))
        OR (ef.[key]=N'Phone' AND REPLACE(TRANSLATE(ef.value,N'()+-.',N'     '),N' ',N'')=REPLACE(TRANSLATE(af.value,N'()+-.',N'     '),N' ',N''))
        OR (NOT(ef.[type]=2 AND af.[type]=2) AND
            ISNULL(NULLIF(LTRIM(RTRIM(ef.value)),N''),N'<NULL>')=ISNULL(NULLIF(LTRIM(RTRIM(af.value)),N''),N'<NULL>'))) THEN 1 ELSE 0 END=0
    UNION ALL
    SELECT CheckName,Item,Field,Expected,Actual,Severity FROM AdditionalIssues
)
SELECT * INTO #StageCheckIssues FROM Issues;
;WITH ExpectedRows AS (SELECT * FROM #StageCheckExpected),
ActualRows AS (SELECT * FROM #StageCheckActual),
AdditionalIssues AS (SELECT * FROM #StageCheckAdditional),
Issues AS (SELECT * FROM #StageCheckIssues),
Sections AS (
    SELECT CheckName FROM ExpectedRows UNION SELECT CheckName FROM ActualRows UNION SELECT CheckName FROM AdditionalIssues
), Summary AS (
    SELECT s.CheckName,
        (SELECT COUNT(*) FROM ExpectedRows e WHERE e.CheckName=s.CheckName) AS ExpectedRows,
        (SELECT COUNT(*) FROM ActualRows a WHERE a.CheckName=s.CheckName) AS ActualRows,
        (SELECT COUNT(*) FROM Issues i WHERE i.CheckName=s.CheckName AND Severity=N'FAIL') AS Failures,
        (SELECT COUNT(*) FROM Issues i WHERE i.CheckName=s.CheckName AND Severity=N'WARN') AS Warnings
    FROM Sections s
), OutputRows AS (
    SELECT 0 AS SortOrder,CONVERT(nvarchar(100),CONCAT(N'ALL STAGE ',@Stage)) AS [Check],
        CASE WHEN EXISTS(SELECT 1 FROM Issues WHERE Severity=N'FAIL') THEN N'FAIL'
             WHEN EXISTS(SELECT 1 FROM Issues WHERE Severity=N'WARN') THEN N'WARN' ELSE N'PASS' END AS [Status],
        CONVERT(nvarchar(1000),N'Overall stored-configuration result') AS Item,CONVERT(nvarchar(128),N'Expected / actual records') AS Field,
        CONVERT(nvarchar(max),(SELECT COUNT(*) FROM ExpectedRows)) AS Expected,
        CONVERT(nvarchar(max),(SELECT COUNT(*) FROM ActualRows)) AS Actual,
        (SELECT COUNT(*) FROM Issues WHERE Severity=N'FAIL') AS Failures,
        (SELECT COUNT(*) FROM Issues WHERE Severity=N'WARN') AS Warnings
    UNION ALL
    SELECT 1,CheckName,CASE WHEN Failures>0 THEN N'FAIL' WHEN Warnings>0 THEN N'WARN' ELSE N'PASS' END,
        N'Section summary',N'Expected / actual records',CONVERT(nvarchar(max),ExpectedRows),CONVERT(nvarchar(max),ActualRows),Failures,Warnings
    FROM Summary
    UNION ALL
    SELECT 2,CheckName,Severity,Item,Field,Expected,Actual,CASE WHEN Severity=N'FAIL' THEN 1 ELSE 0 END,CASE WHEN Severity=N'WARN' THEN 1 ELSE 0 END
    FROM Issues WHERE @ShowDetails=1
)
SELECT [Check],[Status],Item,Field,Expected,Actual,Failures,Warnings
FROM OutputRows ORDER BY SortOrder,[Check],Item,Field;
DROP TABLE IF EXISTS #StageCheckExpected,#StageCheckActual,#StageCheckAdditional,#StageCheckIssues;
